// A reusable textarea
// Generated by Copilot :)

use crossterm::event::{KeyCode, KeyEvent};
use ratatui::{
    Frame,
    layout::{Position, Rect},
    style::{Color, Style},
    widgets::Paragraph,
};

#[derive(Default)]
pub struct TextArea {
    pub text: String,
    pub cursor: usize, // byte index into `text`
}

impl TextArea {
    pub fn new() -> Self {
        Self {
            text: String::new(),
            cursor: 0,
        }
    }

    // ---- Editing Logic -----------------------------------------------------

    pub fn handle_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char(c) => {
                self.text.insert(self.cursor, c);
                self.cursor += c.len_utf8();
            }

            KeyCode::Enter => {
                self.text.insert(self.cursor, '\n');
                self.cursor += '\n'.len_utf8();
            }

            KeyCode::Backspace => self.backspace(),

            KeyCode::Delete => self.delete(),

            KeyCode::Up => self.move_up(true),

            KeyCode::Down => self.move_down(true),

            KeyCode::Left => self.move_left(),

            KeyCode::Right => self.move_right(),

            KeyCode::Home => self.move_up(false),

            KeyCode::End => self.move_down(false),

            _ => {}
        }
    }

    fn move_left(&mut self) {
        if self.cursor > 0 {
            self.cursor = prev_grapheme(self.text.as_str(), self.cursor);
        }
    }

    fn move_right(&mut self) {
        if self.cursor < self.text.len() {
            self.cursor = next_grapheme(self.text.as_str(), self.cursor);
        }
    }

    fn move_up(&mut self, move_line: bool) {
        // Look for the previous \n and move cursor to it
        // Do not change if \n not found
        let mut idx = self.cursor;
        while idx > 0 {
            idx = prev_grapheme(&self.text, idx);
            // I am quite sure we can index the string directly
            // Since \n is a 1 byte char
            if self.text.as_bytes()[idx] == 10 {
                // 10 = utf code for linefeed
                if move_line {
                    self.cursor = idx;
                } else {
                    self.cursor = idx + 1;
                }
                return;
            }
        }
    }

    fn move_down(&mut self, move_line: bool) {
        // Look for the previous \n and move cursor to it
        // Do not change if \n not found
        let mut idx = self.cursor;
        idx = next_grapheme(&self.text, idx);
        while idx < self.text.len() {
            // I am quite sure we can index the string directly
            // Since \n is a 1 byte char
            if self.text.as_bytes()[idx] == 10 {
                // 10 = utf code for linefeed
                if move_line {
                    self.cursor = idx;
                } else {
                    self.cursor = idx - 1;
                }
                return;
            }
            idx = next_grapheme(&self.text, idx);
        }
        // If we reach here, we want to go to final position
        self.cursor = self.text.len();
    }

    fn backspace(&mut self) {
        if self.cursor == 0 {
            return;
        }
        let prev = prev_grapheme(&self.text, self.cursor);
        self.text.drain(prev..self.cursor);
        self.cursor = prev;
    }

    fn delete(&mut self) {
        if self.cursor == self.text.len() {
            return;
        }
        let next = next_grapheme(&self.text, self.cursor);
        self.text.drain(self.cursor..next);
    }

    fn ctrl_backspace(&mut self) {
        if self.cursor == 0 {
            return;
        }
        let mut idx = self.cursor;

        // Skip whitespace first
        while idx > 0 && self.text[..idx].ends_with(char::is_whitespace) {
            idx = prev_grapheme(&self.text, idx);
        }

        // Skip word characters
        while idx > 0 && !self.text[..idx].ends_with(char::is_whitespace) {
            idx = prev_grapheme(&self.text, idx);
        }

        self.text.drain(idx..self.cursor);
        self.cursor = idx;
    }

    // ---- Rendering ---------------------------------------------------------

    pub fn render(&self, f: &mut Frame, area: Rect) {
        let paragraph = Paragraph::new(self.text.clone())
            .style(Style::default().fg(Color::White))
            .wrap(ratatui::widgets::Wrap { trim: false });

        f.render_widget(paragraph, area);

        // Compute cursor position in wrapped text
        let (x, y) = self.cursor_position(area);

        f.set_cursor_position(Position::new(area.x + x, area.y + y));
    }

    fn cursor_position(&self, area: Rect) -> (u16, u16) {
        let mut x = 0;
        let mut y = 0;
        let width = area.width as usize;

        for (i, ch) in self.text.chars().enumerate() {
            if i == self.cursor {
                break;
            }
            if ch == '\n' {
                y += 1;
                x = 0;
            } else {
                x += 1;
                if x >= width {
                    x = 0;
                    y += 1;
                }
            }
        }

        (x as u16, y as u16)
    }
}

// ---- Grapheme helpers -----------------------------------------------------

fn prev_grapheme(s: &str, idx: usize) -> usize {
    unicode_segmentation::UnicodeSegmentation::grapheme_indices(s, true)
        .rev()
        .find(|(i, _)| *i < idx)
        .map(|(i, _)| i)
        .unwrap_or(0)
}

fn next_grapheme(s: &str, idx: usize) -> usize {
    unicode_segmentation::UnicodeSegmentation::grapheme_indices(s, true)
        .find(|(i, _)| *i > idx)
        .map(|(i, _)| i)
        .unwrap_or(s.len())
}
